// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address _user) public {
        vm.assume(_user != address(this));
        vm.assume(_user != address(0));

        vm.prank(_user);
        address ownerBefore = c.owner();

        // The general rule: owner() should always return the deployer (address(this)), not msg.sender
        assertTrue(ownerBefore == address(this));
    }
}

